// Monta a busca de clientes só com os ids que aparecem nas O.S. abertas.
// O IXC às vezes devolve JSON com caractere de controle cru dentro do texto (ex.: quebra de linha na
// mensagem da O.S.), que o n8n recusa. Por isso os nós "Buscar ..." recebem TEXTO e o parse é feito aqui.
const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
const lerIxc = (j) => {
  if (!j) return { error: 'sem resposta' };
  if (j.error) return { error: msgErro(j.error) };
  const raw = j.data;
  if (raw === undefined) return j;
  if (typeof raw !== 'string') return raw;
  const txt = raw.replace(/^﻿/, '').trim();
  try { return JSON.parse(txt); } catch (e) { /* tenta limpar */ }
  try { return JSON.parse(txt.replace(/[\u0000-\u001F]+/g, ' ')); } catch (e) {
    return { error: 'resposta do IXC não é JSON (' + txt.length + ' bytes): ' + txt.slice(0, 180) };
  }
};
const r = lerIxc($('Buscar OS abertas').first().json);
const os = Array.isArray(r.registros) ? r.registros : [];
const ids = [...new Set(os.map(o => String(o.id_cliente || '')).filter(i => /^\d+$/.test(i) && i !== '0'))];
return [{ json: { corpo: {
  qtype: 'cliente.id', query: '0', oper: '>', page: '1',
  rp: String(Math.max(ids.length, 1)), sortname: 'cliente.id', sortorder: 'asc',
  grid_param: JSON.stringify([{ TB: 'cliente.id', OP: 'IN', P: ids.length ? ids.join(',') : '0' }])
} } }];

// Junta as respostas do IXC num "retrato" da base e manda só os campos que o painel usa.
// Se a busca principal falhar, manda {base, erro} — o painel registra e NÃO encerra nenhuma O.S.
// O IXC às vezes devolve JSON com caractere de controle cru dentro do texto (ex.: quebra de linha na
// mensagem da O.S.), que o n8n recusa. Por isso os nós "Buscar ..." recebem TEXTO e o parse é feito aqui.
const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
const lerIxc = (j) => {
  if (!j) return { error: 'sem resposta' };
  if (j.error) return { error: msgErro(j.error) };
  const raw = j.data;
  if (raw === undefined) return j;
  if (typeof raw !== 'string') return raw;
  const txt = raw.replace(/^﻿/, '').trim();
  try { return JSON.parse(txt); } catch (e) { /* tenta limpar */ }
  try { return JSON.parse(txt.replace(/[\u0000-\u001F]+/g, ' ')); } catch (e) {
    return { error: 'resposta do IXC não é JSON (' + txt.length + ' bytes): ' + txt.slice(0, 180) };
  }
};
const cfg = $('Config').first().json;
const base = String(cfg.BASE || '').trim();
const url = String(cfg.IXC_URL || '').trim().replace(/\/+$/, '');
const erro = (msg) => [{ json: { base, erro: String(msg).slice(0, 900) } }];

if (!/^https?:\/\/\S+$/i.test(url) || /PREENCHER/i.test(url)) {
  return erro('Config.IXC_URL não preenchida no workflow do n8n');
}

const r = lerIxc($('Buscar OS abertas').first().json);
if (r.error) return erro('Falha ao buscar O.S. no IXC: ' + msgErro(r.error));
if (r.type === 'error') return erro('IXC recusou a busca de O.S.: ' + (r.message || JSON.stringify(r)));
const total = Number(r.total);
if (!Number.isFinite(total)) return erro('Resposta inesperada do IXC (sem "total"): ' + JSON.stringify(r).slice(0, 300));
const regs = Array.isArray(r.registros) ? r.registros : [];
if (total > 0 && regs.length === 0) return erro('IXC informou ' + total + ' O.S. mas não mandou registros');

const CAMPOS_OS = ['id', 'protocolo', 'status', 'prioridade', 'id_assunto', 'setor', 'id_tecnico', 'id_cliente',
  'id_condominio', 'id_su_diagnostico', 'id_ticket', 'mensagem', 'mensagem_resposta', 'data_abertura', 'data_agenda',
  'data_inicio', 'data_final', 'data_fechamento', 'ultima_atualizacao'];
const os = regs.map(o => {
  const x = {};
  for (const k of CAMPOS_OS) if (o[k] !== undefined) x[k] = (k === 'mensagem' || k === 'mensagem_resposta') ? String(o[k] || '').slice(0, 2000) : o[k];
  return x;
});

const avisos = [];
const dic = (j, nome, campos) => {
  if (!j || j.error || j.type === 'error' || !Array.isArray(j.registros)) {
    if (!(j && Number(j.total) === 0)) avisos.push(nome + ': ' + (j && (j.error ? msgErro(j.error) : j.message) || 'sem registros'));
    return [];
  }
  return j.registros.map(o => { const x = { id: o.id }; for (const c of campos) if (o[c] !== undefined) x[c] = o[c]; return x; });
};
const assuntos = dic(lerIxc($('Buscar assuntos').first().json), 'assuntos', ['assunto']);
const tecnicos = dic(lerIxc($('Buscar técnicos').first().json), 'tecnicos', ['funcionario']);
const setores  = dic(lerIxc($('Buscar setores').first().json), 'setores', ['setor']);
const clientes = os.length ? dic(lerIxc($('Buscar clientes').first().json), 'clientes', ['razao', 'fantasia', 'id_condominio']) : [];
const diagnosticos = dic(lerIxc($('Buscar diagnósticos').first().json), 'diagnosticos', ['descricao']);
const condominios = dic(lerIxc($('Buscar condomínios').first().json), 'condominios', ['condominio']);
const tipo = cfg.TIPO === 'resolvidas' ? 'resolvidas' : 'abertas';

return [{ json: { base, tipo, ixc_url: url, total, os, assuntos, tecnicos, setores, clientes, condominios, diagnosticos, avisos } }];
